1888 void VPWidenRecipe::execute(VPTransformState &State) {
1889   auto &Builder = State.Builder;
1890   switch (Opcode) {
1891   case Instruction::Call:
1892   case Instruction::Br:
1893   case Instruction::PHI:
1894   case Instruction::GetElementPtr:
1895   case Instruction::Select:
1896     llvm_unreachable("This instruction is handled by a different recipe.");
1897   case Instruction::UDiv:
1898   case Instruction::SDiv:
1899   case Instruction::SRem:
1900   case Instruction::URem:
1901   case Instruction::Add:
1902   case Instruction::FAdd:
1903   case Instruction::Sub:
1904   case Instruction::FSub:
1905   case Instruction::FNeg:
1906   case Instruction::Mul:
1907   case Instruction::FMul:
1908   case Instruction::FDiv:
1909   case Instruction::FRem:
1910   case Instruction::Shl:
1911   case Instruction::LShr:
1912   case Instruction::AShr:
1913   case Instruction::And:
1914   case Instruction::Or:
1915   case Instruction::Xor: {
1916     // Just widen unops and binops.
1917     SmallVector<Value *, 2> Ops;
1918     for (VPValue *VPOp : operands())
1919       Ops.push_back(State.get(VPOp));
1920 
1921     Value *V = Builder.CreateNAryOp(Opcode, Ops);
1922 
1923     if (auto *VecOp = dyn_cast<Instruction>(V)) {
1924       applyFlags(*VecOp);
1925       applyMetadata(*VecOp);
1926     }
1927 
1928     // Use this vector value for all users of the original instruction.
1929     State.set(this, V);
1930     break;
1931   }
1932   case Instruction::ExtractValue: {
1933     assert(getNumOperands() == 2 && "expected single level extractvalue");
1934     Value *Op = State.get(getOperand(0));
1935     auto *CI = cast<ConstantInt>(getOperand(1)->getLiveInIRValue());
1936     Value *Extract = Builder.CreateExtractValue(Op, CI->getZExtValue());
1937     State.set(this, Extract);
1938     break;
1939   }
1940   case Instruction::Freeze: {
1941     Value *Op = State.get(getOperand(0));
1942     Value *Freeze = Builder.CreateFreeze(Op);
1943     State.set(this, Freeze);
1944     break;
1945   }
1946   case Instruction::ICmp:
1947   case Instruction::FCmp: {
1948     // Widen compares. Generate vector compares.
1949     bool FCmp = Opcode == Instruction::FCmp;
1950     Value *A = State.get(getOperand(0));
1951     Value *B = State.get(getOperand(1));
1952     Value *C = nullptr;
1953     if (FCmp) {
1954       // Propagate fast math flags.
1955       C = Builder.CreateFCmpFMF(
1956           getPredicate(), A, B,
1957           dyn_cast_or_null<Instruction>(getUnderlyingValue()));
1958     } else {
1959       C = Builder.CreateICmp(getPredicate(), A, B);
1960     }
1961     if (auto *I = dyn_cast<Instruction>(C))
1962       applyMetadata(*I);
1963     State.set(this, C);
1964     break;
1965   }
1966   default:
1967     // This instruction is not vectorized by simple widening.
1968     LLVM_DEBUG(dbgs() << "LV: Found an unhandled opcode : "
1969                       << Instruction::getOpcodeName(Opcode));
1970     llvm_unreachable("Unhandled instruction!");
1971   } // end of switch.
1972 
1973 #if !defined(NDEBUG)
1974   // Verify that VPlan type inference results agree with the type of the
1975   // generated values.
1976   assert(VectorType::get(State.TypeAnalysis.inferScalarType(this), State.VF) ==
1977              State.get(this)->getType() &&
1978          "inferred type and type from generated instructions do not match");
1979 #endif
1980 }
