1369 void VPIRPhi::execute(VPTransformState &State) {
1370   PHINode *Phi = &getIRPhi();
1371   for (const auto &[Idx, Op] : enumerate(operands())) {
1372     VPValue *ExitValue = Op;
1373     auto Lane = vputils::isSingleScalar(ExitValue)
1374                     ? VPLane::getFirstLane()
1375                     : VPLane::getLastLaneForVF(State.VF);
1376     VPBlockBase *Pred = getParent()->getPredecessors()[Idx];
1377     auto *PredVPBB = Pred->getExitingBasicBlock();
1378     BasicBlock *PredBB = State.CFG.VPBB2IRBB[PredVPBB];
1379     // Set insertion point in PredBB in case an extract needs to be generated.
1380     // TODO: Model extracts explicitly.
1381     State.Builder.SetInsertPoint(PredBB, PredBB->getFirstNonPHIIt());
1382     Value *V = State.get(ExitValue, VPLane(Lane));
1383     // If there is no existing block for PredBB in the phi, add a new incoming
1384     // value. Otherwise update the existing incoming value for PredBB.
1385     if (Phi->getBasicBlockIndex(PredBB) == -1)
1386       Phi->addIncoming(V, PredBB);
1387     else
1388       Phi->setIncomingValueForBlock(PredBB, V);
1389   }
1390 
1391   // Advance the insert point after the wrapped IR instruction. This allows
1392   // interleaving VPIRInstructions and other recipes.
1393   State.Builder.SetInsertPoint(Phi->getParent(), std::next(Phi->getIterator()));
1394 }
